#!/bin/bash
# Syntax check (-fsyntax-only) of the C++ generated by rexglue, against the SDK headers. Container, 6 GB / 4 CPUs.
# Usage: syntax_check.sh ['<filter>' [<max error lines>]]   filter = a command the file list is piped through, e.g. 'head -20'
# Needs work/rexglue-tool (the build tree left by tools/build/build_rexglue_tool.sh) for its generated headers.
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
WORK="${EDEN_WORK:-$ROOT/work}"
ENGINE="${ENGINE:-docker}"
exec $ENGINE run --rm -m 6g --cpus 4 -v "$WORK/rexglue-sdk:/src:ro" -v "$WORK/rexglue-tool:/out:ro" -v "$WORK/project:/p:ro" ${IMG:-eden-recomp:build} bash -c '
cd /p/generated/default && FLAGS="-std=c++23 -fsyntax-only -w -fno-char8_t -DREX_PHYSICAL_OFFSET_IN_CODE=0 -I/p/generated/default -I/p/generated -I/p/src -I/src/include -I/out/include -I/src/src -I/src/thirdparty -I/src/thirdparty/simde -I/src/thirdparty/simde/simde -I/src/thirdparty/excrypt/src -I/src/thirdparty/tlsf"
ls eden_recomp.*.cpp | '"${1:-cat}"' | xargs -P4 -I{} sh -c "clang++ $FLAGS {} 2>&1 | grep \"error:\" | sed \"s#^#{}: #\"" | tee /tmp/err.txt | head -${2:-15}
echo "files=$(ls eden_recomp.*.cpp | '"${1:-cat}"' | wc -l) errors=$(wc -l < /tmp/err.txt)"'
